// ─────────────────────────────────────────────────────────────────────────────
// Feature guides - the content behind the "How to use this" dropdown shown in the
// header of every feature page. Keyed by tab (the first path segment, e.g.
// "invoices" for /invoices). Written to help an SMB owner get MAXIMUM value:
//   what  - plain-language: what this does for the business & why it matters
//   steps - how to actually use it, referencing real buttons/sections
//   tips  - power tips: combinations, shortcuts, what "good" looks like
// Generated by reading each real page; edit freely as features evolve.
// ─────────────────────────────────────────────────────────────────────────────
export interface FeatureGuide {
  what: string;
  steps: string[];
  tips: string[];
}

